program.compute:
options = read('/input/options')
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(options, k):
        ids = [record['id'] for record in group]
        if valid(ids):
            result = ids
            break
    if len(result) > 0:
        break

program.effects:
if exists('/output/selection'):
    current = read('/output/selection')
    if valid(current):
        result = current
else:
    write('/output/selection', result)
if status('report') == 'not_sent':
    send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')

